// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.database.entityimport androidx.room.ColumnInfoimport androidx.room.Entityimport androidx.room.ForeignKeyimport androidx.room.Indeximport androidx.room.PrimaryKey/** * NOUS — Conversation session (Table 7). * * @see <a href="docs/strategy/module-3-strategy-v2.md">§8 Schema</a> */@Entity(    tableName = "conversation_sessions",    indices = [Index("started_at")],)data class ConversationSessionEntity(    @PrimaryKey    @ColumnInfo(name = "id")    val id: String,  // SessionId UUID    @ColumnInfo(name = "persona_id")    val personaId: String,    @ColumnInfo(name = "started_at")    val startedAt: Long,    @ColumnInfo(name = "ended_at")    val endedAt: Long? = null,    @ColumnInfo(name = "turn_count")    val turnCount: Int = 0,    @ColumnInfo(name = "summary")    val summary: String? = null,    @ColumnInfo(name = "created_at")    val createdAt: Long,)/** * NOUS — Conversation turn (Table 8). * * @see <a href="docs/strategy/module-3-strategy-v2.md">§8 Schema</a> */@Entity(    tableName = "conversation_turns",    indices = [        Index("session_id"),        Index("timestamp"),    ],    foreignKeys = [        ForeignKey(            entity = ConversationSessionEntity::class,            parentColumns = ["id"],            childColumns = ["session_id"],            onDelete = ForeignKey.CASCADE,        ),    ],)data class ConversationTurnEntity(    @PrimaryKey(autoGenerate = true)    val id: Long = 0,    @ColumnInfo(name = "session_id")    val sessionId: String,    @ColumnInfo(name = "turn_number")    val turnNumber: Int,    @ColumnInfo(name = "user_text")    val userText: String,    @ColumnInfo(name = "brain_response")    val brainResponse: String,    @ColumnInfo(name = "intent_label")    val intentLabel: String? = null,    @ColumnInfo(name = "layer_label")    val layerLabel: String? = null,    @ColumnInfo(name = "correlation_id")    val correlationId: String,    @ColumnInfo(name = "timestamp")    val timestamp: Long,)/** * NOUS — Conversation state (Table 9). * * Crash-safe persistence for NeedsInput pause/resume. 5-minute TTL. * * @see <a href="docs/strategy/module-3-strategy-v2.md">§12 Brain Integration</a> */@Entity(    tableName = "conversation_states",    indices = [        Index(value = ["session_id", "correlation_id"], unique = true),        Index("expires_at"),    ],)data class ConversationStateEntity(    @PrimaryKey(autoGenerate = true)    val id: Long = 0,    @ColumnInfo(name = "session_id")    val sessionId: String,    @ColumnInfo(name = "correlation_id")    val correlationId: String,    @ColumnInfo(name = "skill_id")    val skillId: String,    @ColumnInfo(name = "intent")    val intent: String,  // serialized Intent    @ColumnInfo(name = "stage")    val stage: String,  // PROCESSING, NEEDS_INPUT, RESUMING, COMPLETED, EXPIRED    @ColumnInfo(name = "partial_output")    val partialOutput: String? = null,  // serialized SkillOutput    @ColumnInfo(name = "created_at")    val createdAt: Long,    @ColumnInfo(name = "expires_at")    val expiresAt: Long,) {    fun isExpired(now: Long = System.currentTimeMillis()): Boolean = now > expiresAt}/** * NOUS — User preference (Table 11). * * @see <a href="docs/strategy/module-3-strategy-v2.md">§8 Schema</a> */@Entity(    tableName = "user_preferences",    indices = [Index(value = ["category", "key"], unique = true)],)data class UserPreferenceEntity(    @PrimaryKey(autoGenerate = true)    val id: Long = 0,    @ColumnInfo(name = "category")    val category: String,  // "skill", "response_style", "privacy"    @ColumnInfo(name = "key")    val key: String,    @ColumnInfo(name = "value")    val value: String,    @ColumnInfo(name = "weight")    val weight: Float = 0.5f,    @ColumnInfo(name = "updated_at")    val updatedAt: Long,)/** * NOUS — Skill performance (Table 12). * * @see <a href="docs/strategy/module-3-strategy-v2.md">§8 Schema</a> */@Entity(    tableName = "skill_performance",    indices = [Index(value = ["skill_id", "invoked_at"], unique = true)],)data class SkillPerformanceEntity(    @PrimaryKey(autoGenerate = true)    val id: Long = 0,    @ColumnInfo(name = "skill_id")    val skillId: String,    @ColumnInfo(name = "invoked_at")    val invokedAt: Long,    @ColumnInfo(name = "success")    val success: Boolean,    @ColumnInfo(name = "latency_ms")    val latencyMs: Long,    @ColumnInfo(name = "cost_usd")    val costUsd: Float = 0f,    @ColumnInfo(name = "correlation_id")    val correlationId: String? = null,)/** * NOUS — Brain trace (Table 13, audit log). * * @see <a href="docs/strategy/module-3-strategy-v2.md">§8 Schema</a> */@Entity(    tableName = "brain_traces",    indices = [        Index("session_id"),        Index("created_at"),    ],)data class BrainTraceEntity(    @PrimaryKey    @ColumnInfo(name = "correlation_id")    val correlationId: String,    @ColumnInfo(name = "session_id")    val sessionId: String,    @ColumnInfo(name = "input_redacted")    val inputRedacted: String,    @ColumnInfo(name = "started_at")    val startedAt: Long,    @ColumnInfo(name = "completed_at")    val completedAt: Long,    @ColumnInfo(name = "total_duration_ms")    val totalDurationMs: Long,    @ColumnInfo(name = "layers_json")    val layersJson: String,    @ColumnInfo(name = "final_status")    val finalStatus: String,    @ColumnInfo(name = "final_output")    val finalOutput: String? = null,    @ColumnInfo(name = "final_error")    val finalError: String? = null,    @ColumnInfo(name = "total_cost_usd")    val totalCostUsd: Float = 0f,    @ColumnInfo(name = "total_tokens")    val totalTokens: Int = 0,    @ColumnInfo(name = "created_at")    val createdAt: Long,)/** * NOUS — Workflow trace (Table 14, agentic audit log). * * @see <a href="docs/strategy/module-3-strategy-v2.md">§8 Schema</a> */@Entity(    tableName = "workflow_traces",    indices = [Index("correlation_id"), Index("created_at")],)data class WorkflowTraceEntity(    @PrimaryKey    @ColumnInfo(name = "workflow_id")    val workflowId: String,    @ColumnInfo(name = "correlation_id")    val correlationId: String,    @ColumnInfo(name = "session_id")    val sessionId: String,    @ColumnInfo(name = "user_input")    val userInput: String,    @ColumnInfo(name = "started_at")    val startedAt: Long,    @ColumnInfo(name = "ended_at")    val endedAt: Long,    @ColumnInfo(name = "total_duration_ms")    val totalDurationMs: Long,    @ColumnInfo(name = "total_cost_usd")    val totalCostUsd: Float = 0f,    @ColumnInfo(name = "steps_json")    val stepsJson: String,    @ColumnInfo(name = "final_status")    val finalStatus: String,    @ColumnInfo(name = "final_answer")    val finalAnswer: String? = null,    @ColumnInfo(name = "failure_reason")    val failureReason: String? = null,    @ColumnInfo(name = "created_at")    val createdAt: Long,)